using UnityEngine;
public static class ClearPreviewLixinVfx {
  public static string Run() {
    var all = Object.FindObjectsByType<GameObject>(FindObjectsInactive.Include, FindObjectsSortMode.None);
    int n = 0;
    foreach (var go in all) {
      if (go != null && go.name.StartsWith("PREVIEW_fx_")) { Object.DestroyImmediate(go); n++; }
    }
    return "cleared " + n;
  }
}
